  "Notes": [
    {
      "$type": "ReInvented.Domain.Reporting.Models.Note, ReInvented.Domain.Reporting",
      "Text": "The data provided in this document are the reactions at the supports. Hence, these values shall be multiplied by (-1) to obtain the  forces for foundations' design."
    },
    {
      "$type": "ReInvented.Domain.Reporting.Models.Note, ReInvented.Domain.Reporting",
      "Text": "The local axes shown in the sketches do not correspond to the axes of the pedestals and hence the loads must be re-calculated or transformed to suit to the pedestals' design."
    },
    {
      "$type": "ReInvented.Domain.Reporting.Models.Note, ReInvented.Domain.Reporting",
      "Text": "The circular section pedestal (for center column) is modelled as a circle of simple supports corresponding tothe circle of anchor bolts."
    },
    {
      "$type": "ReInvented.Domain.Reporting.Models.Note, ReInvented.Domain.Reporting",
      "Text": "Load cases 604, 606 provides the difference of loads for sanded condition from their respective operating load cases. Hence the same can be combined with 603, 605 respectively to obtain worst case scenarios while formulating the load combinations."
    },
    {
      "$type": "ReInvented.Domain.Reporting.Models.Note, ReInvented.Domain.Reporting",
      "Text": "Mutual combination of load cases 607 through 612 and their combination with other load cases shall be in accordance with the applicable codes/standards."
    },
    {
      "$type": "ReInvented.Domain.Reporting.Models.Note, ReInvented.Domain.Reporting",
      "Text": "Special loads such as EQ/WL shall be combined with the operating condition loads only e.g., 603."
    },
    {
      "$type": "ReInvented.Domain.Reporting.Models.Note, ReInvented.Domain.Reporting",
      "Text": "The moments (Mx, My, Mz) specified in the <b>Summary of Forces at Supports Group C.G.</b> tables at each PCD are due to the difference between the Load CG to the Origin point of structural system."
    }
  ],
